import json,csv,pathlib,re
D=pathlib.Path(__file__).parent
T=[]; I=[]; P=[]; C=[]
def save():
 for n,o in [('talks',T),('items',I),('problems',P)]: (D/(n+'.json')).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
 with (D/'corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(C)
def talk(r,date,speaker,pages,title,summary):
 T.append(dict(record=r,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))
def item(r,pages,kind,title,notes,statement,fate,refs=[],cls='E',reconstruction=r'',status='',literal='correct with missing hypotheses',match='exact',verification='read the result',problem='',worth='',confidence='high',speaker=None,development='none'):
 n=sum(x['record']==r for x in I)+1
 a=dict(id=f'1982-{r}.{n}',record=r,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or 'As of November 2026, this is an established result with the hypotheses stated above.',literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=refs,confidence=confidence)
 if speaker:a['speaker']=speaker
 I.append(a);return a['id']
def corr(p,place,old,new,evidence,typ='faithful_error',applies='both'):
 C.append(dict(page=p,place=place,transcription_reads=old,should_read=new,evidence=evidence,applies_to=applies,type=typ))
def prob(id,title,statement,occ,status,refs): P.append(dict(id=id,title=title,statement=statement,occurrences=occ,status=status,status_date='2026-11',refs=refs))
