corr('P001092','Euler and formal sums',r'Even zeta formula without pi; sum n^3=-B_2',r'\zeta(2m)=(-1)^{m+1}B_{2m}(2\pi)^{2m}/[2(2m)!];\quad\zeta(-3)=-B_4/4','Both errors are present in the scan; these are analytic-continuation values, not ordinary sums.')
